  ('s-coconut-blueberry-smoothie', 'Coconut Blueberry Smoothie', 'Banana and blueberries blended with coconut milk', 'snack', 'banana', '🥥', 5, 'quick', 282, 3, 44, 13, 6, 25, 10, '[{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"blueberries","amount":100,"unit":"g"},{"name":"coconut milk","amount":60,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Peel the banana and put it in a blender with the blueberries and the coconut milk","Add {100} ml of cold water, blend until smooth and pour into a glass"]'::jsonb, '[]'::jsonb, '["fresh","quick","banana","blueberries","coconut milk","snack"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Смути с кокос и боровинки","description":"Банан и боровинки, пасирани с кокосово мляко","instructions":["Обелете банана и го сложете в блендер с боровинките и кокосовото мляко","Добавете {100} мл студена вода, пасирайте до гладкост и налейте в чаша"],"seasonings":[]},"nl":{"name":"Smoothie met kokos en blauwe bessen","description":"Banaan en blauwe bessen gepureerd met kokosmelk","instructions":["Pel de banaan en doe hem met de blauwe bessen en de kokosmelk in een blender","Voeg {100} ml koud water toe, pureer tot een gladde smoothie en schenk in een glas"],"seasonings":[]}}'::jsonb, 262),
  ('s-ham-cheese-roll-ups', 'Ham and Cheese Roll-Ups', 'Slices of ham rolled around cheese and cucumber sticks', 'snack', 'ham', '🥒', 5, 'quick', 217, 18, 6, 14, 1, 3, 736, '[{"name":"ham","amount":60,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Cut the cheese and the cucumber into sticks","Lay a stick of each on a slice of ham, roll it up, and repeat with the rest"]'::jsonb, '[]'::jsonb, '["quick","light","ham","cheese","cucumber","snack"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Рулца от шунка и кашкавал","description":"Резени шунка, навити около пръчици кашкавал и краставица","instructions":["Нарежете кашкавала и краставицата на пръчици","Сложете по една пръчица от двете върху резен шунка, навийте и повторете с останалите"],"seasonings":[]},"nl":{"name":"Rolletjes van ham en kaas","description":"Plakjes ham opgerold om reepjes kaas en komkommer","instructions":["Snijd de kaas en de komkommer in reepjes","Leg van elk een reepje op een plakje ham, rol op en herhaal met de rest"],"seasonings":[]}}'::jsonb, 263),
  ('s-soy-glazed-tofu-bites', 'Soy-Glazed Tofu Bites', 'Cubes of tofu fried until golden and glazed with soy sauce', 'snack', 'tofu', '🍢', 12, 'quick', 223, 22, 4, 16, 3, 0, 676, '[{"name":"tofu","amount":120,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Pat the tofu dry and cut it into bite-sized cubes","Heat the oil in a pan over medium-high heat and fry the tofu for 6 to 8 minutes, turning, until golden on all sides","Add the soy sauce, toss for 30 seconds until it coats the tofu, and serve"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","soy sauce","oil","stovetop","snack"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Хапки тофу със соева глазура","description":"Кубчета тофу, изпържени до златисто и глазирани със соев сос","instructions":["Подсушете тофуто и го нарежете на кубчета за една хапка","Загрейте олиото в тиган на умерено силен огън и пържете тофуто 6–8 минути, като го обръщате, докато стане златисто от всички страни","Добавете соевия сос, разбъркайте 30 секунди, докато покрие тофуто, и поднесете"],"seasonings":[]},"nl":{"name":"Tofublokjes met sojaglazuur","description":"Blokjes tofu, goudbruin gebakken en geglaceerd met sojasaus","instructions":["Dep de tofu droog en snijd hem in hapklare blokjes","Verhit de olie in een pan op middelhoog tot hoog vuur en bak de tofu 6 tot 8 minuten rondom goudbruin; keer regelmatig","Voeg de sojasaus toe, schep 30 seconden om tot de tofu ermee bedekt is en serveer"],"seasonings":[]}}'::jsonb, 264),
  ('s-yogurt-peanut-dip-apple', 'Peanut Butter Yogurt Dip with Apple', 'Greek yogurt stirred with peanut butter, with apple wedges to dip', 'snack', 'greek yogurt', '🍏', 5, 'quick', 329, 17, 34, 16, 5, 26, 118, '[{"name":"greek yogurt","amount":150,"unit":"g"},{"name":"peanut butter","amount":15,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"}]'::jsonb, '[]'::jsonb, '["Stir the peanut butter into the yogurt until smooth","Core the apple, cut it into wedges and serve them with the dip"]'::jsonb, '[]'::jsonb, '["fresh","quick","hearty","greek yogurt","peanut butter","apple","snack"]'::jsonb, '["vegetarian","gluten-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Дип от кисело мляко и фъстъчено масло с ябълка","description":"Гръцко кисело мляко, разбъркано с фъстъчено масло, с резени ябълка за топене","instructions":["Разбъркайте фъстъченото масло в киселото мляко до гладкост","Почистете ябълката от семките, нарежете я на резени и ги поднесете с дипа"],"seasonings":[]},"nl":{"name":"Yoghurtdip met pindakaas en appel","description":"Griekse yoghurt geroerd met pindakaas, met appelpartjes om te dippen","instructions":["Roer de pindakaas glad door de yoghurt","Verwijder het klokhuis van de appel, snijd hem in partjes en serveer ze met de dip"],"seasonings":[]}}'::jsonb, 265),
  ('s-egg-avocado-toast', 'Egg and Avocado Toast', 'Toast with mashed avocado and sliced boiled eggs', 'snack', 'eggs', '🍳', 12, 'quick', 414, 24, 35, 20, 8, 4, 478, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"avocado","amount":50,"unit":"g"}]'::jsonb, '["pinch of salt","black pepper"]'::jsonb, '["Boil the eggs for 8 minutes, cool them under cold water, peel and slice them","Toast the bread and spread it with the avocado, mashed with a pinch of salt","Lay the egg slices on top and season with black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["quick","hearty","bread","eggs","avocado","stovetop","snack"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Филийка с яйце и авокадо","description":"Препечена филийка с намачкано авокадо и резени варено яйце","instructions":["Сварете яйцата за 8 минути, охладете ги под студена вода, обелете ги и ги нарежете на кръгчета","Препечете хляба и го намажете с авокадото, намачкано с щипка сол","Наредете резените яйце отгоре и поръсете с черен пипер"],"seasonings":["щипка сол","черен пипер"]},"nl":{"name":"Toast met ei en avocado","description":"Toast met geprakte avocado en plakjes gekookt ei","instructions":["Kook de eieren 8 minuten, laat ze schrikken onder koud water, pel ze en snijd ze in plakjes","Rooster het brood en besmeer het met de avocado, geprakt met een snufje zout","Leg de plakjes ei erop en bestrooi met zwarte peper"],"seasonings":["snufje zout","zwarte peper"]}}'::jsonb, 266),
  ('s-bean-cheese-quesadilla', 'Bean and Cheese Quesadilla', 'A folded tortilla filled with kidney beans and melted cheese', 'snack', 'kidney beans', '🌮', 10, 'quick', 372, 18, 47, 13, 7, 6, 831, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"}]'::jsonb, '["pinch of cumin","pinch of salt"]'::jsonb, '["Drain and rinse the beans and roughly mash them with a fork, a pinch of cumin and a pinch of salt","Spread the beans over one half of the tortilla, scatter the grated cheese on top and fold the tortilla over","Toast in a dry pan over medium heat for 2 minutes on each side until crisp and the cheese has melted, then cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","comfort","quick","hearty","tortilla","kidney beans","cheese","stovetop","snack"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Кесадия с боб и кашкавал","description":"Сгъната тортила с червен боб и разтопен кашкавал","instructions":["Отцедете и изплакнете боба и го намачкайте на едро с вилица, щипка кимион и щипка сол","Намажете боба върху едната половина на тортилата, поръсете с настъргания кашкавал и сгънете тортилата","Запечете в сух тиган на среден огън по 2 минути от всяка страна, докато стане хрупкава и кашкавалът се разтопи, след което нарежете на триъгълници"],"seasonings":["щипка кимион","щипка сол"]},"nl":{"name":"Quesadilla met bonen en kaas","description":"Een dubbelgevouwen tortilla gevuld met kidneybonen en gesmolten kaas","instructions":["Laat de bonen uitlekken, spoel ze af en prak ze grof met een vork, een snufje komijn en een snufje zout","Smeer de bonen over één helft van de tortilla, strooi de geraspte kaas erover en vouw de tortilla dicht","Bak in een droge pan op middelhoog vuur 2 minuten per kant, tot hij knapperig is en de kaas gesmolten is, en snijd dan in punten"],"seasonings":["snufje komijn","snufje zout"]}}'::jsonb, 267),
  ('s-tofu-scramble-wrap', 'Tofu Scramble Wrap', 'A tortilla filled with tofu scrambled with peppers', 'snack', 'tofu', '🌯', 10, 'quick', 385, 23, 35, 19, 5, 4, 458, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"tofu","amount":100,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of turmeric","pinch of salt","black pepper"]'::jsonb, '["Dice the peppers and crumble the tofu with your fingers","Heat the oil in a pan over medium heat, cook the peppers for 2 minutes, then add the tofu, the turmeric, salt and black pepper and fry for 4 minutes","Spoon the scramble onto the tortilla, roll it up and cut it in half"]'::jsonb, '["stovetop"]'::jsonb, '["quick","hearty","tortilla","tofu","peppers","oil","stovetop","snack"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Врап с бъркано тофу","description":"Тортила с тофу, забъркано с чушки","instructions":["Нарежете чушките на кубчета и натрошете тофуто с пръсти","Загрейте олиото в тиган на среден огън, запържете чушките за 2 минути, след което добавете тофуто, куркумата, сол и черен пипер и пържете 4 минути","Сложете сместа върху тортилата, навийте я и я разрежете наполовина"],"seasonings":["щипка куркума","щипка сол","черен пипер"]},"nl":{"name":"Wrap met roertofu","description":"Een tortilla gevuld met roertofu en paprika","instructions":["Snijd de paprika in blokjes en verkruimel de tofu met je vingers","Verhit de olie in een pan op middelhoog vuur, bak de paprika 2 minuten, voeg dan de tofu, de kurkuma, zout en zwarte peper toe en bak 4 minuten","Schep de roertofu op de tortilla, rol hem op en snijd hem doormidden"],"seasonings":["snufje kurkuma","snufje zout","zwarte peper"]}}'::jsonb, 268),
  ('s-chickpea-avocado-bowl', 'Chickpea and Avocado Bowl', 'Chickpeas tossed with avocado and tomato', 'snack', 'chickpeas', '🥗', 5, 'quick', 335, 13, 43, 15, 15, 9, 378, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"avocado","amount":70,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["squeeze of lemon juice","pinch of salt","black pepper"]'::jsonb, '["Drain and rinse the chickpeas and put them in a bowl","Dice the avocado and the tomato and add them to the bowl","Toss with a squeeze of lemon juice, a pinch of salt and black pepper"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","hearty","chickpeas","avocado","tomato","snack"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа с нахут и авокадо","description":"Нахут, разбъркан с авокадо и домат","instructions":["Отцедете и изплакнете нахута и го сложете в купа","Нарежете авокадото и домата на кубчета и ги добавете в купата","Разбъркайте с няколко капки лимонов сок, щипка сол и черен пипер"],"seasonings":["няколко капки лимонов сок","щипка сол","черен пипер"]},"nl":{"name":"Kom met kikkererwten en avocado","description":"Kikkererwten gemengd met avocado en tomaat","instructions":["Laat de kikkererwten uitlekken, spoel ze af en doe ze in een kom","Snijd de avocado en de tomaat in blokjes en doe ze in de kom","Meng met een kneepje citroensap, een snufje zout en zwarte peper"],"seasonings":["kneepje citroensap","snufje zout","zwarte peper"]}}'::jsonb, 269)
